<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{storeToRefs}from'pinia';import{RouterLink,useRoute}from'vue-router';import OrderFulfillmentSubnav from '../components/OrderFulfillmentSubnav.vue';import{useOrderStore}from'../runtime/order-store';import'./order-views.css';const route=useRoute();const store=useOrderStore();const{differences,loading,error,saving}=storeToRefs(store);const item=computed(()=>differences.value.find(v=>v.id===String(route.params.differenceId))??null);const message=ref('');const money=(v:number)=>`¥${(v/100).toFixed(2)}`;async function resolve(outcome:'reship'|'ignore'|'refund'){if(!item.value)return;await store.loadFulfillment(item.value.orderId);if(await store.resolveDifference(item.value.id,outcome)){await store.loadDifferences();message.value=outcome==='reship'?'差异已转补发，订单重新进入待出库':outcome==='refund'?'短装退款已确认；发货时原子形成应收与差异贷项':'已接受短装，可继续确认发货'}}onMounted(()=>store.loadDifferences())
</script>
<template><section class="order-page"><OrderFulfillmentSubnav/><div v-if="loading" class="order-state"><strong>正在加载差异详情…</strong></div><div v-else-if="error||!item" class="order-state error"><strong>无法打开差异单</strong><p>{{ error??'差异单不存在' }}</p></div><template v-else><header class="order-detail-header"><div><RouterLink class="order-back" to="/orders/differences">← 差异单列表</RouterLink><p class="eyebrow">{{ item.differenceNo }}</p><h1>{{ item.customerSnapshot.name }}</h1></div><RouterLink class="order-button" :to="`/orders/${item.orderId}`">订单详情</RouterLink></header><p v-if="message" class="order-panel" style="padding:9px 12px">{{ message }}</p><section class="order-card"><h2>差异信息</h2><dl class="order-grid"><div><dt>状态</dt><dd>{{ item.status }}</dd></div><div><dt>实际仓库</dt><dd>{{ item.warehouseSnapshot.name }}</dd></div><div><dt>原因</dt><dd>{{ item.reason }}</dd></div><div><dt>差异金额</dt><dd>{{ money(item.differenceAmountCents) }}</dd></div></dl></section><section class="order-card"><h2>差异明细</h2><div class="order-table-wrap"><table class="order-table"><thead><tr><th>商品</th><th>订货</th><th>实出</th><th>差异</th><th class="order-money">差异金额</th></tr></thead><tbody><tr v-for="line in item.lines" :key="line.orderLineId"><td>{{ line.productNameSnapshot }}<small>{{ line.skuCodeSnapshot }}</small></td><td>{{ line.orderedQuantityMilli/1000 }}</td><td>{{ line.actualQuantityMilli/1000 }}</td><td>{{ line.differenceQuantityMilli/1000 }} {{ line.unitSnapshot.name }}</td><td class="order-money">{{ money(line.differenceAmountCents) }}</td></tr></tbody></table></div></section><section v-if="item.status==='pending-confirmation'" class="order-card"><h2>确认处理</h2><div class="order-detail-actions"><button class="order-button primary" :disabled="saving" @click="resolve('reship')">补发</button><button class="order-button" :disabled="saving" @click="resolve('ignore')">忽略短装</button><button class="order-button" :disabled="saving" @click="resolve('refund')">短装退款</button></div><p class="order-notice">短装退款不生成退货入库；发货时先形成完整应收，再在同一事务追加差异贷项。</p></section><section v-else class="order-card"><h2>处理结果</h2><p>{{ item.outcome==='reship'?'补发':item.outcome==='ignore'?'忽略短装':item.outcome==='refund'?'短装退款（待发货形成贷项）':'未处理' }} · {{ item.confirmedBy?.name??'—' }}</p></section></template></section></template>
